};

function draftRows(response) {
  const ranges = response?.valueRanges;
  const [values] = ranges?.length === 1 ? [ranges[0]?.valueRange?.values] : [];
  if (!Array.isArray(values)) throw new Error("Google Sheets did not return the configured range.");
  return values;
}

function planDrafts(response) {
  const [header, ...values] = draftRows(response);
  const columns = ["DATA", "PROMPT", "TITOLO", "ID POST", "IDEA ID", "DRAFT STATE"];
  if (!Array.isArray(header) || !columns.every((column, i) => header[i] === column)) {
    throw new Error("Use the six required columns in the stated order.");
  }
  const plans = [];
  const ids = new Set();
  for (const [i, cells] of values.entries()) {
    const [date, prompt, title, postId, ideaId, state] = cells;
    if (ideaId) {
      if (typeof ideaId !== "string" || !/^[a-z][a-z0-9-]{0,62}$/.test(ideaId) || ids.has(ideaId)) {
        throw new Error("Give each idea a unique lowercase IDEA ID.");
      }
      ids.add(ideaId);
    }
    if (!prompt || postId || state) continue;
    if (
      !ideaId ||
      typeof prompt !== "string" ||
      !prompt.trim() ||
      prompt.length > 12000 ||
      date ||
      title
    ) {
      throw new Error(
        "Review incomplete rows before drafting. Each new idea needs an ID, a prompt and empty output cells.",
      );
    }
    plans.push({ row: i + 1, ideaId, prompt, slug: "sheet-idea-" + ideaId });
  }
  return plans;
}

return planDrafts($input.first().json).map((plan) => ({ json: { plan }, pairedItem: { item: 0 } }));

